const fs = require('fs');
const path = require('path');

const endpoint = 'http://127.0.0.1:63686/status';
const outputPath = path.join(__dirname, 'results', 'status.json');

async function main() {
  const res = await fetch(endpoint);
  const body = await res.json();
  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  fs.writeFileSync(outputPath, JSON.stringify({ status: body.status }, null, 2) + '\n');
  console.log(`wrote status=${body.status} to ${outputPath}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

